class Solution:
    def minWindow(self, s: str, t: str) -> str:
        need = [0] * 128
        for ch in t:
            need[ord(ch)] += 1
        missing = len(t)
        left = 0
        best_l = 0
        best_len = len(s) + 1
        for right, ch in enumerate(s):
            idx = ord(ch)
            if need[idx] > 0:
                missing -= 1
            need[idx] -= 1
            while missing == 0:
                cur_len = right - left + 1
                if cur_len < best_len:
                    best_len = cur_len
                    best_l = left
                lidx = ord(s[left])
                need[lidx] += 1
                if need[lidx] > 0:
                    missing += 1
                left += 1
        return "" if best_len > len(s) else s[best_l : best_l + best_len]

